(function(E){ const x = E["exam-10"] = E["exam-10"] || {units:{}}; (x.units = x.units || {})["x10-r3"] = {"id":"x10-r3","patterns":["RA-mind","GT3-nature","PARA-research","PARA-cause","TR-NGvsF","TR-whosevoice","TR-samewords","TR-paraphrase","TR-limit","TR-plural","TR-hedge"],"title":{"en":"Reading 3: Passage 3 / Section 3","tr":"Reading 3: Passage 3 / Section 3","fa":"Reading ۳: متن ۳ (Passage 3) / بخش ۳ (Section 3)"},"objective":{"en":"In this lesson you will learn to follow a writer who challenges a common belief: answer multiple choice questions on the evidence, complete a summary with words from the passage, and decide YES, NO or NOT GIVEN on the writer’s views.","tr":"Bu derste yaygın bir inanışa karşı çıkan bir yazarı takip etmeyi öğreneceksin: kanıtlarla ilgili çoktan seçmeli soruları cevaplayacak, bir özeti metindeki kelimelerle tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نویسنده‌ای را که یک باور رایج را به چالش می‌کشد دنبال کنی: به سؤال‌های چندگزینه‌ای درباره‌ی شواهد جواب بدهی، یک خلاصه را با کلمه‌های متن کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"objectiveGT":{"en":"In this lesson you will learn to complete a summary of the background, match statements to seven people quoted in a long article, and answer multiple choice questions, including one on the writer’s tone.","tr":"Bu derste arka planı anlatan bir özeti tamamlamayı, uzun bir makalede alıntılanan yedi kişiyle ifadeleri eşleştirmeyi ve biri yazarın tonuyla ilgili olmak üzere çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری خلاصه‌ی زمینه را کامل کنی، جمله‌ها را با هفت نفری که در یک مقاله‌ی بلند نقل قول شده‌اند جور کنی و به سؤال‌های چندگزینه‌ای، از جمله یکی درباره‌ی لحن نویسنده، جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 3: an argument about people","tr":"Reading Passage 3: insanlar üzerine bir tartışma","fa":"Reading Passage 3: استدلالی درباره‌ی آدم‌ها"},"objective":{"en":"In this lesson you will learn to follow a writer who challenges a common belief: answer multiple choice questions on the evidence, complete a summary with words from the passage, and decide YES, NO or NOT GIVEN on the writer’s views.","tr":"Bu derste yaygın bir inanışa karşı çıkan bir yazarı takip etmeyi öğreneceksin: kanıtlarla ilgili çoktan seçmeli soruları cevaplayacak, bir özeti metindeki kelimelerle tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نویسنده‌ای را که یک باور رایج را به چالش می‌کشد دنبال کنی: به سؤال‌های چندگزینه‌ای درباره‌ی شواهد جواب بدهی، یک خلاصه را با کلمه‌های متن کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: is kindness natural?","tr":"Bu sınav: iyilik doğal mı?","fa":"این آزمون: آیا مهربانی ذاتی است؟"},"intro":{"en":"Psychology and society are among the most frequent Academic topics, and Passage 3 often argues against a common belief. Track the writer’s position from the first paragraph: it shapes every YES/NO answer.","tr":"Psikoloji ve toplum en sık çıkan Academic konular arasındadır ve Passage 3 çoğu zaman yaygın bir inanışa karşı çıkar. Yazarın tutumunu ilk paragraftan itibaren takip et: her YES/NO cevabını o belirler.","fa":"روان‌شناسی و جامعه از پرتکرارترین موضوع‌های Academic هستند و Passage 3 اغلب علیه یک باور رایج استدلال می‌کند. موضع نویسنده را از پاراگراف اول دنبال کن: همه‌ی جواب‌های YES/NO از آن شکل می‌گیرند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x10-r3-ctx","exam":true,"patterns":["RA-mind","PARA-research"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"An argument about human nature","tr":"İnsan doğası üzerine bir tartışma","fa":"بحثی درباره‌ی سرشت انسان"},"asks":{"en":"The writer challenges a traditional view of people, using evidence from children, traditional societies, emergencies and experiments, then admits its limits and draws a lesson. Multiple choice and a summary test the evidence; YES/NO/NOT GIVEN tests the writer’s opinions.","tr":"Yazar, çocuklardan, geleneksel toplumlardan, acil durumlardan ve deneylerden kanıtlar kullanarak insanlarla ilgili geleneksel bir görüşe karşı çıkıyor, sonra sınırlarını kabul edip bir ders çıkarıyor. Çoktan seçmeli sorular ve özet kanıtları ölçer; YES/NO/NOT GIVEN yazarın görüşlerini ölçer.","fa":"نویسنده با شواهدی از بچه‌ها، جامعه‌های سنتی، موقعیت‌های اضطراری و آزمایش‌ها دیدگاهی سنتی درباره‌ی آدم‌ها را به چالش می‌کشد، بعد محدودیت‌هایش را می‌پذیرد و درسی می‌گیرد. سؤال‌های چندگزینه‌ای و خلاصه شواهد را می‌سنجند؛ YES/NO/NOT GIVEN نظرهای نویسنده را."},"fields":["The traditional view","Evidence from children","Evidence from traditional societies","Behaviour in emergencies","The limits","Experiments","The writer’s lesson"],"words":[{"a":"self-interested","b":"acting only to benefit yourself","tr":"çıkarcı","fa":"نفع‌طلب"},{"a":"challenge a view","b":"suggest it is wrong / question it","tr":"bir görüşe karşı çıkmak","fa":"به چالش کشیدن یک دیدگاه"},{"a":"spontaneously","b":"without being asked / naturally","tr":"kendiliğinden","fa":"خودجوش"},{"a":"a reward","b":"a prize / something given for doing it","tr":"ödül","fa":"پاداش"},{"a":"shared","b":"divided among everyone / not kept","tr":"paylaşılmış","fa":"تقسیم‌شده"},{"a":"mocked","b":"laughed at / made fun of","tr":"alay edilmiş","fa":"مسخره‌شده"},{"a":"modest","b":"not boasting","tr":"alçakgönüllü","fa":"فروتن"},{"a":"panic","b":"sudden fear that stops clear thinking","tr":"panik","fa":"وحشت"},{"a":"fragile","b":"easily weakened","tr":"kırılgan","fa":"شکننده"},{"a":"to my mind","b":"in my view / I believe","tr":"bence","fa":"به نظر من"},{"a":"seems unlikely","b":"probably not","tr":"pek olası görünmüyor","fa":"بعید به نظر می‌رسد"}],"traps":[{"en":"\"None of this means that...\" limits the writer’s own argument. A statement that goes further than the writer (equally kind to everyone) is NO.","tr":"\"Bunların hiçbiri ... anlamına gelmez\" yazarın kendi argümanını sınırlar. Yazardan daha ileri giden bir ifade (herkese eşit derecede iyi) NO’dur.","fa":"«هیچ‌کدام از این‌ها یعنی ... نیست» استدلال خود نویسنده را محدود می‌کند. جمله‌ای که از نویسنده جلوتر برود (با همه به یک اندازه مهربان) NO است."},{"en":"A hedge is still a view: \"it seems doubtful that diet alone explains this\" tells you the writer disagrees with \"diet explains this\".","tr":"Çekinceli bir ifade de görüştür: \"bunu yalnızca beslenmenin açıkladığı şüpheli görünüyor\", yazarın \"bunu beslenme açıklar\" görüşüne katılmadığını gösterir.","fa":"قید احتیاط هم نظر است: «بعید است فقط رژیم غذایی این را توضیح بدهد» نشان می‌دهد نویسنده با «رژیم غذایی این را توضیح می‌دهد» مخالف است."},{"en":"The summary words must come from the passage in the same form: \"shared\", \"mocked\", not synonyms.","tr":"Özet kelimeleri metinden aynı biçimde gelmeli: eş anlamlılar değil, \"shared\", \"mocked\".","fa":"کلمه‌های خلاصه باید به همان شکل از متن بیایند: «shared»، «mocked»، نه مترادف‌ها."}],"example":{"text":"\"It is often said that teenagers are lazy. In my experience, they work extremely hard when they care about the task.\"","item":"Statement: Teenagers are naturally lazy. (views of the writer)","answer":"NO","why":{"en":"\"It is often said\" is not the writer; \"in my experience, they work extremely hard\" disagrees.","tr":"\"It is often said\" yazar değil; \"deneyimime göre çok sıkı çalışıyorlar\" karşı çıkıyor.","fa":"«اغلب گفته می‌شود» نویسنده نیست؛ «به تجربه‌ی من خیلی سخت کار می‌کنند» مخالف است."}}},{"id":"RA-mind-arg","ctx":["RA-mind"],"title":{"en":"Arguments about learning and society","tr":"Öğrenme ve toplum üzerine tartışma yazıları","fa":"نوشته‌های استدلالی درباره‌ی یادگیری و جامعه"},"asks":{"en":"An argument about education, behaviour or society: should children learn handwriting, does praise help, can wisdom be learned. The writer reports other views and gives their own; multiple choice and summaries follow the argument.","tr":"Eğitim, davranış ya da toplum üzerine bir tartışma yazısı: çocuklar el yazısı öğrenmeli mi, övgü işe yarar mı, bilgelik öğrenilebilir mi. Yazar başka görüşleri aktarır ve kendi görüşünü verir; çoktan seçmeli sorular ve özetler tartışmanın akışını izler.","fa":"نوشته‌ای استدلالی درباره‌ی آموزش، رفتار یا جامعه: آیا بچه‌ها باید دست‌خط یاد بگیرند، آیا تعریف کردن کمک می‌کند، آیا خرد یادگرفتنی است. نویسنده نظرهای دیگران را نقل می‌کند و نظر خودش را می‌دهد؛ چندگزینه‌ای و خلاصه‌ها مسیر استدلال را دنبال می‌کنند."},"fields":["The writer agrees with the government’s view. (YES / NO / NOT GIVEN)","What does the writer say about earlier research?","The writer’s purpose in the final paragraph is to...","Summary: many teachers ___ the importance of..."],"words":[{"a":"in favour of","b":"supports / argues for","tr":"lehinde","fa":"موافقِ"},{"a":"against","b":"opposes / objects to","tr":"aleyhinde","fa":"مخالفِ"},{"a":"misguided","b":"wrong / based on a mistake","tr":"yanlış temelli","fa":"نادرست"},{"a":"reasonable","b":"fair / makes sense","tr":"makul","fa":"منطقی"},{"a":"exaggerate","b":"overstate / make it sound bigger","tr":"abartmak","fa":"اغراق کردن"},{"a":"widely held","b":"many people believe","tr":"yaygın","fa":"رایج"},{"a":"it remains to be seen","b":"we do not know yet","tr":"henüz belli değil","fa":"هنوز معلوم نیست"},{"a":"evidence suggests","b":"research indicates","tr":"kanıtlar gösteriyor ki","fa":"شواهد نشان می‌دهد"},{"a":"sceptical","b":"doubtful","tr":"şüpheci","fa":"تردیدآمیز"},{"a":"a balanced view","b":"both sides","tr":"dengeli bir bakış","fa":"دیدگاه متعادل"},{"a":"ultimately","b":"in the end","tr":"sonuç olarak","fa":"در نهایت"},{"a":"rightly","b":"correctly / with good reason","tr":"haklı olarak","fa":"به‌درستی"}],"traps":[{"en":"The writer’s opinion often sits in one word: \"rightly\", \"wrongly\", \"surprisingly\". Watch the adverbs.","tr":"Yazarın görüşü çoğu zaman tek bir kelimededir: \"rightly\", \"wrongly\", \"surprisingly\". Zarflara dikkat et.","fa":"نظر نویسنده اغلب در یک کلمه است: «rightly»، «wrongly»، «surprisingly». به قیدها دقت کن."},{"en":"Summary with a box: the words in the box are paraphrases. Choose by meaning and by grammar.","tr":"Kutulu özet: kutudaki kelimeler başka ifadelerdir. Hem anlama hem dilbilgisine göre seç.","fa":"خلاصه با جعبه: کلمه‌های جعبه هم‌معنی‌اند. هم بر اساس معنی و هم بر اساس دستور انتخاب کن."}],"example":{"text":"Praising children for being clever is widely recommended. I believe this advice is misguided: children praised for their intelligence often avoid difficult tasks, in case they fail.","item":"Statement: The writer agrees that children should be praised for being clever.  (YES / NO / NOT GIVEN)","answer":"NO","why":{"en":"The advice is \"widely recommended\", but the writer calls it \"misguided\": NO.","tr":"Tavsiye \"yaygın olarak öneriliyor\" ama yazar ona \"yanlış\" diyor: NO.","fa":"این توصیه «رایج است»، ولی نویسنده آن را «نادرست» می‌داند: NO."}},"track":"academic","general":true,"patterns":["RA-mind"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Choices, a summary, the writer’s views","tr":"Seçimler, bir özet, yazarın görüşleri","fa":"گزینه‌ها، خلاصه، نظرهای نویسنده"},"body":{"en":"Questions 27-30: choose A, B, C or D. Questions 31-35: complete a summary with ONE WORD ONLY from the passage (there is no box). Questions 36-40: YES, NO or NOT GIVEN on the writer’s views.","tr":"Soru 27-30: A, B, C ya da D’yi seç. Soru 31-35: bir özeti metinden YALNIZCA BİR KELİMEYLE tamamla (kutu yok). Soru 36-40: yazarın görüşleri için YES, NO ya da NOT GIVEN.","fa":"سؤال‌های ۲۷ تا ۳۰: A، B، C یا D را انتخاب کن. سؤال‌های ۳۱ تا ۳۵: خلاصه را فقط با یک کلمه از متن کامل کن (کادری نیست). سؤال‌های ۳۶ تا ۴۰: YES، NO یا NOT GIVEN درباره‌ی نظرهای نویسنده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the first and last paragraphs first: they tell you the writer’s position.","tr":"Önce ilk ve son paragrafları oku: yazarın tutumunu söylerler.","fa":"اول پاراگراف اول و آخر را بخوان: موضع نویسنده را می‌گویند."},{"en":"For each multiple choice question, find the paragraph and test all four options.","tr":"Her çoktan seçmeli soru için paragrafı bul ve dört seçeneği de test et.","fa":"برای هر سؤال چندگزینه‌ای پاراگراف را پیدا کن و هر چهار گزینه را بسنج."},{"en":"For the summary, locate the paragraph from its topic and copy each word exactly.","tr":"Özet için konusundan paragrafı bul ve her kelimeyi aynen kopyala.","fa":"برای خلاصه، از روی موضوعش پاراگراف را پیدا کن و هر کلمه را دقیق کپی کن."},{"en":"For YES/NO/NOT GIVEN, ask whether the writer’s view goes as far as the statement.","tr":"YES/NO/NOT GIVEN için yazarın görüşünün ifade kadar ileri gidip gitmediğini sor.","fa":"برای YES/NO/NOT GIVEN بپرس آیا نظر نویسنده به اندازه‌ی جمله جلو می‌رود."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"YES, NO or NOT GIVEN?","tr":"YES mi, NO mu, NOT GIVEN mı?","fa":"YES، NO یا NOT GIVEN؟"},"table":{"headers":{"en":["The writer","The answer"],"tr":["Yazar","Cevap"],"fa":["نویسنده","جواب"]},"rows":[["states the same view","YES"],["states the opposite view","NO"],["gives no view on this point","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One view, step by step","tr":"Bir görüş, adım adım","fa":"یک نظر، قدم به قدم"},"instruction":"Do the following statements agree with the views of the writer?","text":"\"Cities are often blamed for loneliness. I am not convinced: some of the loneliest people I have met lived in small villages.\"","item":"Statement: Living in a city is the main cause of loneliness.","answer":"NO","walk":[{"en":"Find the writer’s voice: \"I am not convinced\".","tr":"Yazarın sesini bul: \"I am not convinced\".","fa":"صدای نویسنده را پیدا کن: «I am not convinced»."},{"en":"\"Often blamed\" reports other people’s view.","tr":"\"Sık sık suçlanır\" başkalarının görüşünü aktarıyor.","fa":"«اغلب مقصر دانسته می‌شود» نظر دیگران را نقل می‌کند."},{"en":"The writer doubts the city is to blame: NO.","tr":"Yazar şehrin suçlu olduğundan şüpheli: NO.","fa":"نویسنده تردید دارد که شهر مقصر باشد: NO."}]},"quick":{"prompt":"Writer: \"Exercise improves mood. Whether it also improves memory, I cannot say.\" Statement: \"Exercise improves memory.\"","options":["YES","NOT GIVEN","NO"],"correct":1,"why":{"en":"\"I cannot say\" means the writer gives no view on memory.","tr":"\"Söyleyemem\" yazarın hafıza konusunda görüş vermediğini gösterir.","fa":"«نمی‌توانم بگویم» یعنی نویسنده درباره‌ی حافظه نظری نمی‌دهد."}},"remember":{"en":"Read the writer’s position first, copy summary words exactly, and check how far each view goes.","tr":"Önce yazarın tutumunu oku, özet kelimelerini aynen kopyala ve her görüşün ne kadar ileri gittiğine bak.","fa":"اول موضع نویسنده را بخوان، کلمه‌های خلاصه را دقیق کپی کن و ببین هر نظر تا کجا پیش می‌رود."},"type":"explain","id":"c-x10-r3-e","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 3","title":{"en":"Born to share?","tr":"Paylaşmak için mi doğduk?","fa":"آیا برای تقسیم کردن به دنیا آمده‌ایم؟"},"timed":20,"ctx":["RA-mind"],"intro":"You should spend about 20 minutes on Questions 27-40, which are based on Reading Passage 3 below.","passage":"Born to share?\n\nFor much of the last few centuries, a gloomy idea has dominated Western thinking about human nature. According to this view, people are naturally self-interested: left to ourselves, we would take what we wanted and look after no one but our own families. Civilisation, laws and religion exist to hold these instincts in check. The idea has been especially influential in economics, where models of behaviour have often assumed that individuals act only to benefit themselves. I want to suggest that this picture is not merely incomplete but, in important ways, wrong.\n\nConsider first the evidence from very young children. In one well-known series of experiments, toddlers aged around eighteen months watched an adult who was struggling with a simple task, such as reaching for a pen that had been dropped or opening a cupboard while carrying a pile of books. Without being asked, and without any reward, most of the children went to help. More strikingly, when some children were given a small toy each time they helped, they later helped less often than children who had never been rewarded at all, as if the reward had changed helping from something they wanted to do into a kind of work. Behaviour that appears so early, and so spontaneously, seems unlikely to be something children have simply been taught by their parents.\n\nA second line of evidence comes from societies that live by hunting and gathering, which offer some idea of how humans lived for most of their history. Anthropologists have repeatedly found that in such groups, the meat from a successful hunt is shared among all families, not kept by the hunter. People who try to take more than their share are often mocked, and a hunter who boasts about his success is quickly brought down to size. Successful hunters are expected to be modest about their achievements. These customs make sense in an environment where any family might go hungry after a few unlucky days, and where survival depended on cooperation. The great inequalities of wealth and power that we now take for granted seem to have appeared only after the beginning of farming, when people could store food and pass land to their children.\n\nEven in modern societies, our behaviour in a crisis contradicts the gloomy view. Popular films show disasters as moments of panic, with people pushing each other aside to escape. Researchers who have studied real emergencies, from fires to floods, describe something very different. Most people stay calm, help strangers and share what they have, often at some risk to themselves. Panic does occur, but it is far rarer than we imagine. In several studies, the first people to help were not police officers or firefighters but ordinary passers-by, who simply saw that someone needed them.\n\nNone of this means that humans are simply kind. Our generosity has clear limits, and it is usually strongest towards people we see as members of our own group: our family, our neighbours, people who share our language or beliefs. Towards outsiders, we can be indifferent or even hostile. Any honest account of human nature must explain both our readiness to share and our tendency to divide the world into \"us\" and \"them\".\n\nLaboratory games used by economists tell a similar mixed story. When people are given a sum of money and asked how much to share with an anonymous stranger, a purely self-interested player would keep everything. In practice, most people give away a substantial part, even when no one will ever know what they decided. Similar results have been found in many different countries, although the amounts people give vary from one culture to another. Yet generosity in these games also falls when people are encouraged to think of the situation as a business transaction. How a situation is described, it seems, can switch our cooperative instincts on or off.\n\nThis, to my mind, is the most important lesson. If kindness is natural but fragile, then the way we design our schools, workplaces and economic systems matters a great deal. Systems that reward only individual success, and that treat every relationship as a deal, may gradually weaken the instincts that make cooperation possible. Systems that recognise shared effort may strengthen them.\n\nThe old view of human nature was not invented from nothing; people can certainly be greedy and cruel. But it describes only part of who we are, and by taking the worst of human behaviour as the whole story, it has shaped policies that may have made that behaviour more common. We would do better to start from a more balanced view: that humans are, by nature, capable of remarkable generosity, provided that the conditions allow it.","groups":[{"instruction":"Questions 27-30. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 27-30 on your answer sheet.","qtype":"mcq","questions":[{"n":27,"kind":"mcq","prompt":"What is the writer doing in the first paragraph?","options":["A explaining why economists study kindness","B describing the history of civilisation","C presenting a view that he intends to challenge","D arguing that laws are unnecessary"],"correct":2,"evidence":"I want to suggest that this picture is not merely incomplete but, in important ways, wrong","why":{"en":"He describes the \"gloomy idea\" and then says it is \"in important ways, wrong\".","tr":"\"Kasvetli fikri\" anlatıyor, sonra bunun \"önemli açılardan yanlış\" olduğunu söylüyor.","fa":"«ایده‌ی بدبینانه» را توصیف می‌کند و بعد می‌گوید «از جهت‌های مهمی غلط است»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":28,"kind":"mcq","prompt":"What did the experiments with young children show?","options":["A Children helped only when an adult asked them to.","B Rewards made children less likely to help later.","C Older children were more helpful than younger ones.","D Children learned to help by copying their parents."],"correct":1,"evidence":"they later helped less often than children who had never been rewarded at all","why":{"en":"Children given a toy \"later helped less often\". They helped \"without being asked\", and the writer doubts it was taught.","tr":"Oyuncak verilen çocuklar \"sonra daha az yardım etti\". \"İstenmeden\" yardım ettiler; yazar bunun öğretildiğinden şüpheli.","fa":"بچه‌هایی که اسباب‌بازی گرفتند «بعداً کمتر کمک کردند». «بی‌آنکه از آن‌ها بخواهند» کمک کردند و نویسنده شک دارد این را یاد گرفته باشند."},"trap":["TR-paraphrase","TR-samewords"]},{"n":29,"kind":"mcq","prompt":"According to the writer, what happens in most real emergencies?","options":["A People generally behave calmly and help others.","B People panic and push others aside.","C People wait for the emergency services.","D People protect only their own families."],"correct":0,"evidence":"Most people stay calm, help strangers and share what they have","why":{"en":"Films show panic, but researchers find that \"most people stay calm, help strangers\".","tr":"Filmler paniği gösteriyor ama araştırmacılar \"çoğu insanın sakin kalıp yabancılara yardım ettiğini\" buluyor.","fa":"فیلم‌ها وحشت را نشان می‌دهند، اما پژوهشگرها می‌بینند «بیشتر آدم‌ها آرام می‌مانند و به غریبه‌ها کمک می‌کنند»."},"trap":["TR-samewords"]},{"n":30,"kind":"mcq","prompt":"What limit to human kindness does the writer mention?","options":["A It disappears in times of crisis.","B It is found only in small societies.","C It depends on being rewarded.","D It is strongest towards people in our own group."],"correct":3,"evidence":"it is usually strongest towards people we see as members of our own group","why":{"en":"\"Usually strongest towards people we see as members of our own group\"; towards outsiders we can be indifferent.","tr":"\"Genellikle kendi grubumuzun üyesi saydığımız insanlara karşı en güçlü\"; yabancılara karşı kayıtsız olabiliriz.","fa":"«معمولاً نسبت به کسانی که عضو گروه خودمان می‌دانیم از همه قوی‌تر است»؛ با غریبه‌ها ممکن است بی‌تفاوت باشیم."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 31-35. Complete the summary below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 31-35 on your answer sheet.","qtype":"summary","summaryTitle":"Sharing in hunter-gatherer societies","questions":[{"n":31,"kind":"gap","prompt":"In many hunter-gatherer societies, meat from a successful hunt is ___ among all families.","accept":["shared"],"limit":1,"evidence":"the meat from a successful hunt is shared among all families","why":{"en":"\"Is shared among all families, not kept by the hunter\".","tr":"\"Avcıda kalmaz, bütün aileler arasında paylaştırılır\".","fa":"«بین همه‌ی خانواده‌ها تقسیم می‌شود، نه اینکه پیش شکارچی بماند»."},"trap":["TR-paraphrase"]},{"n":32,"kind":"gap","prompt":"People who take more than their share are often ___.","accept":["mocked"],"limit":1,"evidence":"are often mocked","why":{"en":"\"People who try to take more than their share are often mocked.\"","tr":"\"Payından fazlasını almaya çalışanlarla sık sık alay edilir.\"","fa":"«کسانی که سعی می‌کنند بیش از سهمشان بردارند اغلب مسخره می‌شوند»."},"trap":["TR-paraphrase"]},{"n":33,"kind":"gap","prompt":"Good hunters are expected to be ___ about what they achieve.","accept":["modest"],"limit":1,"evidence":"Successful hunters are expected to be modest","why":{"en":"\"Expected to be modest about their achievements\"; boasting is punished.","tr":"\"Başarıları konusunda alçakgönüllü olmaları beklenir\"; böbürlenmek cezalandırılır.","fa":"«از آن‌ها انتظار می‌رود درباره‌ی موفقیتشان فروتن باشند»؛ لاف زدن تنبیه می‌شود."},"trap":["TR-paraphrase"]},{"n":34,"kind":"gap","prompt":"These customs probably arose because survival depended on ___.","accept":["cooperation"],"limit":1,"evidence":"survival depended on cooperation","why":{"en":"\"Where survival depended on cooperation\".","tr":"\"Hayatta kalmanın işbirliğine bağlı olduğu yerde\".","fa":"«جایی که زنده ماندن به همکاری بستگی داشت»."},"trap":["TR-paraphrase"]},{"n":35,"kind":"gap","prompt":"Large inequalities seem to have appeared only after the start of ___.","accept":["farming"],"limit":1,"evidence":"only after the beginning of farming","why":{"en":"\"Only after the beginning of farming, when people could store food\".","tr":"\"Ancak tarımın başlamasından sonra, insanlar yiyecek depolayabildiğinde\".","fa":"«فقط بعد از آغاز کشاورزی، وقتی مردم می‌توانستند غذا ذخیره کنند»."},"trap":["TR-limit"]}]},{"instruction":"Questions 36-40. Do the following statements agree with the views of the writer in Reading Passage 3? In boxes 36-40 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":36,"kind":"ynng","prompt":"Economists have been right to assume that people act only in their own interest.","correct":"NO","evidence":"not merely incomplete but, in important ways, wrong","why":{"en":"The writer calls the self-interest picture \"in important ways, wrong\".","tr":"Yazar çıkarcı insan tablosuna \"önemli açılardan yanlış\" diyor.","fa":"نویسنده تصویر انسانِ نفع‌طلب را «از جهت‌های مهمی غلط» می‌داند."},"trap":["TR-whosevoice"]},{"n":37,"kind":"ynng","prompt":"Children’s willingness to help is mainly something they learn from their parents.","correct":"NO","evidence":"seems unlikely to be something children have simply been taught by their parents","why":{"en":"Behaviour that appears so early \"seems unlikely to be something children have simply been taught\".","tr":"Bu kadar erken ortaya çıkan davranışın \"çocuklara sadece öğretilmiş bir şey olması pek olası görünmüyor\".","fa":"رفتاری که این‌قدر زود ظاهر می‌شود «بعید به نظر می‌رسد فقط چیزی باشد که به بچه‌ها یاد داده‌اند»."},"trap":["TR-whosevoice","TR-hedge"]},{"n":38,"kind":"ynng","prompt":"People in hunter-gatherer societies are happier than people in modern societies.","correct":"NOT GIVEN","evidence":"which offer some idea of how humans lived for most of their history","why":{"en":"The writer discusses sharing and equality, but gives no view on happiness.","tr":"Yazar paylaşmayı ve eşitliği tartışıyor ama mutluluk konusunda görüş vermiyor.","fa":"نویسنده درباره‌ی تقسیم و برابری حرف می‌زند، اما درباره‌ی شادی نظری نمی‌دهد."},"trap":["TR-NGvsF"]},{"n":39,"kind":"ynng","prompt":"The way organisations are designed can make people less cooperative.","correct":"YES","evidence":"may gradually weaken the instincts that make cooperation possible","why":{"en":"Systems that reward only individual success \"may gradually weaken\" cooperative instincts.","tr":"Yalnızca bireysel başarıyı ödüllendiren sistemler işbirliği içgüdülerini \"yavaş yavaş zayıflatabilir\".","fa":"سیستم‌هایی که فقط موفقیت فردی را پاداش می‌دهند ممکن است غریزه‌های همکاری را «کم‌کم ضعیف کنند»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":40,"kind":"ynng","prompt":"Humans are naturally equally kind to everyone they meet.","correct":"NO","evidence":"None of this means that humans are simply kind","why":{"en":"\"None of this means that humans are simply kind\": generosity is strongest within our own group.","tr":"\"Bunların hiçbiri insanların sadece iyi kalpli olduğu anlamına gelmiyor\": cömertlik en çok kendi grubumuza.","fa":"«هیچ‌کدام از این‌ها یعنی آدم‌ها فقط مهربان‌اند نیست»: سخاوت بیشتر نسبت به گروه خودمان است."},"trap":["TR-whosevoice","TR-samewords"]}]}],"id":"c-x10-r3-d","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Kindness is natural but fragile.\" Fragile means...","options":["easily weakened or damaged","very strong","rarely seen"],"correct":0,"why":{"en":"Fragile = easily broken or weakened.","tr":"Fragile = kolayca kırılan ya da zayıflayan.","fa":"fragile یعنی زود شکننده یا ضعیف‌شونده."}},{"tests":"paraphrase","point":2,"prompt":"A summary says \"people who take too much are laughed at\". Which word in a passage would you look for?","options":["modest","shared","mocked"],"correct":2,"why":{"en":"To mock = to laugh at someone unkindly.","tr":"Mock = biriyle alay etmek.","fa":"mock یعنی مسخره کردن کسی."}},{"tests":"method","point":3,"prompt":"Where is the writer’s overall position usually clearest in an argument passage?","options":["in the middle examples","in the first and last paragraphs","in the title only"],"correct":1,"why":{"en":"Writers usually state their view at the start and repeat it at the end.","tr":"Yazarlar görüşlerini genelde başta söyler, sonda tekrarlar.","fa":"نویسنده‌ها معمولاً نظرشان را اول می‌گویند و آخر تکرار می‌کنند."}},{"tests":"trap","point":3,"prompt":"Writer: \"Sport can build confidence, but it is not a cure for every problem.\" Statement: \"Sport solves all the problems young people face.\"","options":["NO","YES","NOT GIVEN"],"correct":0,"why":{"en":"\"Not a cure for every problem\" contradicts \"solves all the problems\".","tr":"\"Her soruna çare değil\", \"bütün sorunları çözer\" ile çelişiyor.","fa":"«درمان همه‌ی مشکل‌ها نیست» با «همه‌ی مشکل‌ها را حل می‌کند» تناقض دارد."}}],"id":"c-x10-r3-x","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"},"gt":{"explain":{"title":{"en":"GT Reading Section 3: a long article with many voices","tr":"GT Reading Section 3: birçok sesin olduğu uzun bir makale","fa":"GT Reading Section 3: مقاله‌ای بلند با چند صدا"},"objective":{"en":"In this lesson you will learn to complete a summary of the background, match statements to seven people quoted in a long article, and answer multiple choice questions, including one on the writer’s tone.","tr":"Bu derste arka planı anlatan bir özeti tamamlamayı, uzun bir makalede alıntılanan yedi kişiyle ifadeleri eşleştirmeyi ve biri yazarın tonuyla ilgili olmak üzere çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری خلاصه‌ی زمینه را کامل کنی، جمله‌ها را با هفت نفری که در یک مقاله‌ی بلند نقل قول شده‌اند جور کنی و به سؤال‌های چندگزینه‌ای، از جمله یکی درباره‌ی لحن نویسنده، جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"People","tr":"Kişi","fa":"آدم‌ها"},"value":"A-G"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: giving a river back its bends","tr":"Bu sınav: bir nehre kıvrımlarını geri vermek","fa":"این آزمون: برگرداندن پیچ‌وخم‌های یک رودخانه"},"intro":{"en":"Nature and the environment are among the most frequent GT Section 3 topics. Articles like this one report a project through the voices of the people involved, so matching features is the central task.","tr":"Doğa ve çevre, GT Section 3’ün en sık çıkan konularındandır. Bunun gibi makaleler bir projeyi ilgili insanların sesleriyle anlatır; bu yüzden özellik eşleştirme asıl görevdir.","fa":"طبیعت و محیط زیست از پرتکرارترین موضوع‌های GT Section 3 هستند. مقاله‌هایی مثل این، یک پروژه را با صدای آدم‌های درگیرش روایت می‌کنند، پس جور کردن ویژگی‌ها کار اصلی است."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x10-r3gt-ctx","exam":true,"patterns":["GT3-nature","PARA-cause","PARA-research"],"often":{"pattern":"GT3-nature","n":12,"of":40,"label":{"en":"Comes up often in the real exam: 12 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 12’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۲ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"An article on restoring nature","tr":"Doğayı onarmak üzerine bir makale","fa":"مقاله‌ای درباره‌ی احیای طبیعت"},"asks":{"en":"A general-interest article tells the story of an environmental project: how a place was changed in the past, the problems this caused, what was done, who was affected, and the results. Seven people give their views.","tr":"Genel ilgi çeken bir makale bir çevre projesinin hikâyesini anlatıyor: bir yerin geçmişte nasıl değiştirildiği, bunun yol açtığı sorunlar, ne yapıldığı, kimlerin etkilendiği ve sonuçlar. Yedi kişi görüşlerini söylüyor.","fa":"یک مقاله‌ی عمومی داستان یک پروژه‌ی محیط‌زیستی را تعریف می‌کند: یک جا در گذشته چطور تغییر داده شد، چه مشکل‌هایی پیش آمد، چه کاری انجام شد، چه کسانی تحت تأثیر قرار گرفتند و نتیجه‌ها چه بود. هفت نفر نظرشان را می‌گویند."},"fields":["The past change","The problems","The project","Costs and land","Local reactions","Results so far","The future"],"words":[{"a":"straightened","b":"made straight / bends filled in","tr":"düzleştirilmiş","fa":"صاف‌شده"},{"a":"embankments","b":"high banks / walls of earth","tr":"setler","fa":"خاکریزها"},{"a":"carry away","b":"wash away / remove","tr":"sürükleyip götürmek","fa":"با خود بردن"},{"a":"restore","b":"give back its old shape","tr":"eski hâline getirmek","fa":"احیا کردن"},{"a":"the main aim","b":"the main purpose / what it was really for","tr":"asıl amaç","fa":"هدف اصلی"},{"a":"shared between","b":"paid by several organisations","tr":"... arasında paylaşılmış","fa":"تقسیم‌شده بین"},{"a":"paid fairly","b":"compensation / a fair price","tr":"adil ödeme","fa":"پرداخت منصفانه"},{"a":"consulted","b":"talked to / asked for their views","tr":"danışılmış","fa":"نظرخواهی‌شده"},{"a":"spawn","b":"breed / lay eggs","tr":"yumurtlamak","fa":"تخم‌ریزی کردن"},{"a":"too early to judge","b":"it will take years to know","tr":"karar vermek için çok erken","fa":"برای قضاوت خیلی زود"},{"a":"cautious","b":"careful / not yet sure","tr":"temkinli","fa":"محتاط"},{"a":"reduced flooding","b":"no serious floods since","tr":"selleri azalttı","fa":"سیل را کم کرد"}],"traps":[{"en":"Seven people, six statements: one person is not used, and each statement must match that person’s own words, not the paragraph around them.","tr":"Yedi kişi, altı ifade: bir kişi kullanılmaz ve her ifade, çevresindeki paragrafla değil o kişinin kendi sözleriyle eşleşmelidir.","fa":"هفت نفر، شش جمله: یک نفر استفاده نمی‌شود و هر جمله باید با حرف خود آن شخص جور باشد، نه با پاراگراف دورش."},{"en":"The writer’s own description (\"the main aim was...\") and a person’s quote can say different things. Read who is speaking.","tr":"Yazarın kendi anlatımı (\"asıl amaç...\") ile bir kişinin alıntısı farklı şeyler söyleyebilir. Kimin konuştuğuna bak.","fa":"توصیف خود نویسنده («هدف اصلی...») و نقل قول یک شخص ممکن است حرف‌های متفاوتی بزنند. ببین چه کسی حرف می‌زند."}],"example":{"text":"\"The park ranger, Ali Shah, is delighted with the new paths. A neighbour, Rose Day, is less sure: ‘They have brought far too many cars.’\"","item":"Who thinks the project has caused a traffic problem?","answer":"Rose Day","why":{"en":"Shah is delighted; the complaint about cars is in Day’s own words.","tr":"Shah memnun; arabalarla ilgili şikâyet Day’in kendi sözlerinde.","fa":"شاه خوشحال است؛ شکایت از ماشین‌ها در حرف خود دِی است."}}},{"id":"GT3-nature","ctx":["GT3-nature"],"title":{"en":"Nature and the environment","tr":"Doğa ve çevre","fa":"طبیعت و محیط زیست"},"asks":{"en":"A longer text about wildlife or the environment: turtles, storks, farmland returning to nature, plastic in the sea. Multiple choice, summaries and matching features test causes, efforts and results.","tr":"Yaban hayatı ya da çevre hakkında daha uzun bir metin: kaplumbağalar, leylekler, doğaya dönen tarım arazileri, denizdeki plastik. Çoktan seçmeli sorular, özetler ve özellik eşleştirme nedenleri, çabaları ve sonuçları sınar.","fa":"متنی بلندتر درباره‌ی حیات وحش یا محیط زیست: لاک‌پشت‌ها، لک‌لک‌ها، زمین‌های کشاورزی که به طبیعت برمی‌گردند، پلاستیک در دریا. چندگزینه‌ای، خلاصه‌ها و جورکردن ویژگی‌ها علت‌ها، تلاش‌ها و نتیجه‌ها را می‌سنجند."},"fields":["Why did the birds disappear from the area?","What did volunteers do first?","Summary: the young turtles head for the ___.","Which organisation does each statement refer to?"],"words":[{"a":"wildlife","b":"animals and birds","tr":"yaban hayatı","fa":"حیات وحش"},{"a":"habitat","b":"the place where it lives","tr":"yaşam alanı","fa":"زیستگاه"},{"a":"return","b":"come back / reappear","tr":"geri dönmek","fa":"برگشتن"},{"a":"breed","b":"have young / nest","tr":"üremek","fa":"تولیدمثل کردن"},{"a":"pollution","b":"dirty water or air / waste","tr":"kirlilik","fa":"آلودگی"},{"a":"volunteers","b":"unpaid helpers","tr":"gönüllüler","fa":"داوطلب‌ها"},{"a":"monitor","b":"watch and record","tr":"izlemek","fa":"پایش کردن"},{"a":"release","b":"set free","tr":"serbest bırakmak","fa":"رها کردن"},{"a":"population","b":"the number of animals","tr":"popülasyon","fa":"جمعیت"},{"a":"threatened","b":"in danger","tr":"tehdit altında","fa":"در معرض خطر"},{"a":"reintroduce","b":"bring back to an area","tr":"yeniden yerleştirmek","fa":"بازگرداندن به منطقه"},{"a":"rewilding","b":"letting land return to nature","tr":"doğaya geri bırakma","fa":"بازگرداندن زمین به طبیعت"}],"traps":[{"en":"Cause and result in one paragraph: the question may ask for the cause, but the result comes first in the text.","tr":"Neden ve sonuç aynı paragrafta: soru nedeni sorabilir ama metinde önce sonuç gelir.","fa":"علت و نتیجه در یک پاراگراف: سؤال ممکن است علت را بخواهد، ولی در متن اول نتیجه می‌آید."},{"en":"Summary from a box: two words in the box are close in meaning. Check the exact sense.","tr":"Kutudan özet: kutudaki iki kelime anlamca yakındır. Tam anlamı kontrol et.","fa":"خلاصه از جعبه: دو کلمه‌ی جعبه معنی نزدیکی دارند. معنی دقیق را چک کن."}],"example":{"text":"Storks stopped nesting in the region in the 1940s, after the wet meadows where they fed were drained for farming. They returned only when some of the meadows were flooded again in 2016.","item":"Why did storks stop nesting in the region?  A hunting   B the loss of wet meadows   C cold winters","answer":"B","why":{"en":"\"After the wet meadows where they fed were drained\": the cause is the loss of their feeding grounds.","tr":"\"Beslendikleri ıslak çayırlar kurutulduktan sonra\": neden, beslenme alanlarının yok olması.","fa":"«بعد از اینکه چمنزارهای خیسی که در آن غذا می‌خوردند زهکشی شدند»: علت از بین رفتن محل تغذیه است."}},"track":"gt","general":true,"patterns":["GT3-nature"],"often":{"pattern":"GT3-nature","n":12,"of":40,"label":{"en":"Comes up often in the real exam: 12 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 12’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۲ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Summary, people, choices","tr":"Özet, kişiler, seçimler","fa":"خلاصه، آدم‌ها، گزینه‌ها"},"body":{"en":"Questions 28-30: complete a summary of the opening paragraphs with ONE WORD ONLY. Questions 31-36: match six statements to seven people, A-G. Questions 37-40: choose A, B, C or D; the last question asks about the article as a whole.","tr":"Soru 28-30: açılış paragraflarının özetini YALNIZCA BİR KELİMEYLE tamamla. Soru 31-36: altı ifadeyi yedi kişiyle (A-G) eşleştir. Soru 37-40: A, B, C ya da D’yi seç; son soru makalenin bütününü soruyor.","fa":"سؤال‌های ۲۸ تا ۳۰: خلاصه‌ی پاراگراف‌های اول را فقط با یک کلمه کامل کن. سؤال‌های ۳۱ تا ۳۶: شش جمله را با هفت نفر (A تا G) جور کن. سؤال‌های ۳۷ تا ۴۰: A، B، C یا D را انتخاب کن؛ سؤال آخر درباره‌ی کل مقاله است."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Do the summary first: it covers only the first paragraphs.","tr":"Önce özeti yap: yalnızca ilk paragrafları kapsar.","fa":"اول خلاصه را حل کن: فقط پاراگراف‌های اول را پوشش می‌دهد."},{"en":"Mark each person’s name and job, and underline their quoted words.","tr":"Her kişinin adını ve işini işaretle, alıntılanan sözlerinin altını çiz.","fa":"اسم و شغل هر نفر را علامت بزن و زیر نقل قولش خط بکش."},{"en":"Use the job to predict: a flood officer talks about floods, a farmer about land.","tr":"Tahmin için mesleği kullan: sel görevlisi sellerden, çiftçi araziden söz eder.","fa":"از شغل برای حدس استفاده کن: مسئول سیل درباره‌ی سیل حرف می‌زند و کشاورز درباره‌ی زمین."},{"en":"For the tone question, weigh the whole article: benefits, worries and doubts.","tr":"Ton sorusu için makalenin tamamını tart: faydalar, endişeler ve şüpheler.","fa":"برای سؤال لحن، کل مقاله را بسنج: فایده‌ها، نگرانی‌ها و تردیدها."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Tone: not too strong, not too weak","tr":"Ton: ne fazla güçlü ne fazla zayıf","fa":"لحن: نه خیلی تند، نه خیلی ضعیف"},"table":{"headers":{"en":["If the article...","The tone is..."],"tr":["Makale...","Ton..."],"fa":["اگر مقاله...","لحن..."]},"rows":[["reports benefits and some doubts","generally positive"],["only praises","enthusiastic"],["mainly lists problems","critical"],["gives facts but no judgement","neutral"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One person, step by step","tr":"Bir kişi, adım adım","fa":"یک نفر، قدم به قدم"},"instruction":"Match each statement with the correct person.","text":"\"The headteacher, Mr Lowe, says the garden has improved attendance. A parent, Mrs Kaur, would like it to be open at weekends too.\"","item":"Statement: The garden should be available more often.","answer":"Mrs Kaur","walk":[{"en":"The idea: more access, more often.","tr":"Fikir: daha fazla erişim, daha sık.","fa":"ایده: دسترسی بیشتر، دفعه‌های بیشتر."},{"en":"Lowe talks about attendance, a different point.","tr":"Lowe devamlılıktan söz ediyor; farklı bir nokta.","fa":"لو درباره‌ی حضور در مدرسه حرف می‌زند؛ نکته‌ی دیگری است."},{"en":"Kaur wants it open at weekends too: Mrs Kaur.","tr":"Kaur hafta sonları da açık olmasını istiyor: Mrs Kaur.","fa":"کائور می‌خواهد آخر هفته‌ها هم باز باشد: Mrs Kaur."}]},"quick":{"prompt":"An article describes a new cycle path, quotes happy cyclists, and ends with a shopkeeper’s worry about lost parking. Which tone fits best?","options":["completely negative","neutral, with no opinions at all","generally positive, with a concern"],"correct":2,"why":{"en":"Mostly positive voices, plus one concern: generally positive.","tr":"Çoğunlukla olumlu sesler ve bir endişe: genel olarak olumlu.","fa":"بیشتر صداهای مثبت به‌اضافه‌ی یک نگرانی: روی‌هم‌رفته مثبت."}},"remember":{"en":"Summary first, names and jobs marked, quotes matched, and the tone judged on the whole article.","tr":"Önce özet, isimler ve meslekler işaretli, alıntılar eşleşmiş, ton bütün makaleye göre değerlendirilmiş.","fa":"اول خلاصه، اسم‌ها و شغل‌ها علامت‌خورده، نقل قول‌ها جور شده و لحن بر اساس کل مقاله."},"type":"explain","id":"c-x10-r3-e-gt","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 3","title":{"en":"Giving a river back its bends","tr":"Bir nehre kıvrımlarını geri vermek","fa":"برگرداندن پیچ‌وخم‌های یک رودخانه"},"timed":20,"ctx":["GT3-nature"],"texts":[{"title":"Giving a river back its bends","kind":"article","body":"For nearly two hundred years, the River Lenn ran across the valley floor in a dead-straight line, as if someone had drawn it with a ruler. In a sense, someone had. In the early nineteenth century, landowners wanted more land for crops and grazing, so the winding river was straightened, its bends filled in and its banks raised with high embankments to keep the water off the fields. The new channel did its job: the fields stayed dry, and the farms grew. But the change had consequences that nobody fully understood at the time.\n\nA straight river flows faster than a winding one. Water that once spread slowly across the meadows in winter was now forced along the channel at speed, carrying away the gravel from the riverbed and delivering floodwater quickly to the town of Ashby downstream. Over the twentieth century, Ashby flooded more and more often. At the same time, the fast-flowing water and the loss of gravel made the river a poor place for fish to breed, and the wet meadows that had supported birds and wild flowers slowly disappeared.\n\nSix years ago, a partnership of the local council, a wildlife trust and several landowners began an unusual project. Instead of building higher walls to protect the town, they decided to give the river back its old shape. Using maps from before the straightening, engineers dug a new, winding channel that followed the river's original course, removed sections of the embankments and allowed the water to spill onto the surrounding fields when levels were high. The main aim, according to the project manager, Anja Halvorsen, was not to restore the landscape for its own sake but to slow the river down. \"Every bend and every field that holds water for a few hours means less water arriving in Ashby at the same moment,\" she says.\n\nThe work took two summers and cost around three million pounds, shared between the council, the wildlife trust and a government flood-protection fund. It also required the cooperation of farmers, since the new channel and the meadows that would flood in winter took up land that had been used for crops. One of them, Bryn Talfryn, admits that he was not keen at first. \"Nobody likes to see good land go under water,\" he says. \"But we were paid fairly for it, and that made the decision a lot easier. The cattle graze those meadows in summer anyway.\"\n\nNot everyone in the valley was happy. Some residents of the villages near the river feared that their own homes would be flooded instead of the town. \"We heard about the plans when the diggers turned up,\" says Colin Brady, who lives beside one of the new meadows. \"I think people would have been far less worried if the project team had talked to us properly at the start.\" The partnership has since held regular public meetings, and no homes in the villages have been flooded.\n\nThe first real test came during the first winter after the work was finished, when heavy rain fell for several days. As planned, the river overflowed into the meadows, which held the water like a sponge and released it slowly over the following week. In Ashby, the river rose, but it stayed within its banks. The hydrologist Eleanor Voss, who measured the water levels, was impressed by how much the meadows could hold. \"At their peak, they were storing as much water as a small reservoir,\" she says. According to the council's flood officer, Imran Siddiqui, the project has clearly reduced flooding in the town. \"In the five winters since the work was completed, we have had no serious floods in Ashby, despite two storms that would almost certainly have flooded the centre in the past,\" he says.\n\nThe benefits for wildlife appeared even faster than expected. Gravel has begun to build up again on the bends, and Jenna Marlow, secretary of the local fishing club, reports that trout and salmon have returned to spawn in the river for the first time in living memory. Wading birds now feed on the wet meadows in winter, and wild flowers have spread along the new banks.\n\nScientists are more cautious. Professor Harriet Quaye, an ecologist who has studied the valley since before the work began, says the early signs are encouraging but warns that rivers change over decades rather than years. \"It is too early to judge the long-term results,\" she says. \"The river is still finding its way, and some of the bends may move.\" Even so, the project has attracted visitors from across the country, and Halvorsen believes its lesson is clear. \"Many of our rivers were straightened for the same reasons,\" she says. \"I would like to see the same approach tried on many of them.\""}],"groups":[{"text":0,"instruction":"Questions 28-30. Complete the summary below. Choose ONE WORD ONLY from the text for each answer.","qtype":"summary","summaryTitle":"The River Lenn before the project","questions":[{"n":28,"kind":"gap","prompt":"In the early nineteenth century the river was ___ to create more farmland.","accept":["straightened"],"limit":1,"evidence":"the winding river was straightened","why":{"en":"\"The winding river was straightened\" so landowners had more land.","tr":"\"Kıvrımlı nehir düzleştirildi\", böylece toprak sahiplerinin daha çok arazisi oldu.","fa":"«رودخانه‌ی پیچ‌درپیچ صاف شد» تا زمین بیشتری برای مالکان باشد."},"trap":["TR-paraphrase"]},{"n":29,"kind":"gap","prompt":"High ___ were built to keep water off the fields.","accept":["embankments"],"limit":1,"evidence":"its banks raised with high embankments","why":{"en":"\"Its banks raised with high embankments to keep the water off the fields\". Plural.","tr":"\"Suyu tarlalardan uzak tutmak için kıyıları yüksek setlerle yükseltildi\". Çoğul.","fa":"«کناره‌هایش با خاکریزهای بلند بالا آورده شد تا آب از مزرعه‌ها دور بماند». جمع."},"trap":["TR-plural"]},{"n":30,"kind":"gap","prompt":"The faster water carried away the ___ from the riverbed.","accept":["gravel"],"limit":1,"evidence":"carrying away the gravel from the riverbed","why":{"en":"\"Carrying away the gravel from the riverbed\".","tr":"\"Nehir yatağındaki çakılı alıp götürerek\".","fa":"«شن‌ریزه‌ی بستر رودخانه را با خودش می‌برد»."},"trap":["TR-limit"]}]},{"text":0,"instruction":"Questions 31-36. Look at the following statements (Questions 31-36) and the list of people below. Match each statement with the correct person, A-G. Write the correct letter, A-G, in boxes 31-36 on your answer sheet. NB You may use any letter more than once.","qtype":"match-features","bank":["A Bryn Talfryn","B Eleanor Voss","C Imran Siddiqui","D Jenna Marlow","E Harriet Quaye","F Colin Brady","G Anja Halvorsen"],"questions":[{"n":31,"kind":"match","prompt":"The project has reduced the number of floods in the town.","correct":2,"evidence":"the project has clearly reduced flooding in the town","why":{"en":"Siddiqui, the flood officer: no serious floods in five winters.","tr":"Sel görevlisi Siddiqui: beş kışta ciddi sel olmadı.","fa":"صدیقی، مسئول سیل: در پنج زمستان هیچ سیل جدی‌ای نیامد."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":32,"kind":"match","prompt":"Financial compensation made it easier to accept the loss of land.","correct":0,"evidence":"we were paid fairly for it, and that made the decision a lot easier","why":{"en":"Talfryn: \"we were paid fairly for it, and that made the decision a lot easier\".","tr":"Talfryn: \"bunun için adil bir ödeme aldık ve bu kararı çok kolaylaştırdı\".","fa":"تالفرین: «پول منصفانه‌ای گرفتیم و همین تصمیم را خیلی راحت‌تر کرد»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":33,"kind":"match","prompt":"Fish are breeding in the river again.","correct":3,"evidence":"trout and salmon have returned to spawn in the river","why":{"en":"Marlow: trout and salmon \"have returned to spawn\". Spawn = breed.","tr":"Marlow: alabalık ve somon \"yumurtlamak için geri döndü\". Spawn = üremek.","fa":"مارلو: قزل‌آلا و ماهی آزاد «برای تخم‌ریزی برگشته‌اند». spawn یعنی تولیدمثل."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":34,"kind":"match","prompt":"It will take many years to know whether the project has succeeded.","correct":4,"evidence":"It is too early to judge the long-term results","why":{"en":"Quaye: \"too early to judge the long-term results\"; rivers change over decades.","tr":"Quaye: \"uzun vadeli sonuçları değerlendirmek için çok erken\"; nehirler on yıllar içinde değişir.","fa":"کوای: «برای قضاوت درباره‌ی نتیجه‌های درازمدت خیلی زود است»؛ رودخانه‌ها در طول دهه‌ها تغییر می‌کنند."},"trap":["TR-whosevoice","TR-hedge"]},{"n":35,"kind":"match","prompt":"Local people should have been given more information at the beginning.","correct":5,"evidence":"if the project team had talked to us properly at the start","why":{"en":"Brady: people \"would have been far less worried\" if the team had talked to them at the start.","tr":"Brady: ekip başta onlarla düzgün konuşsaydı insanlar \"çok daha az endişelenirdi\".","fa":"بردی: اگر تیم پروژه از اول درست با آن‌ها حرف زده بود، مردم «خیلی کمتر نگران می‌شدند»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":36,"kind":"match","prompt":"The same method should be used on other rivers.","correct":6,"evidence":"I would like to see the same approach tried on many of them","why":{"en":"Halvorsen: many rivers were straightened, and she would like the same approach \"tried on many of them\".","tr":"Halvorsen: birçok nehir düzleştirildi; aynı yöntemin \"birçoğunda denenmesini\" istiyor.","fa":"هالورسن: خیلی از رودخانه‌ها صاف شده‌اند و دوست دارد همین روش «روی خیلی‌هایشان امتحان شود»."},"trap":["TR-whosevoice","TR-paraphrase"]}]},{"text":0,"instruction":"Questions 37-40. Choose the correct letter, A, B, C or D.","qtype":"mcq","questions":[{"n":37,"kind":"mcq","prompt":"What was the main purpose of the project?","options":["A to make the landscape look as it once did","B to slow down the water reaching the town","C to create more land for farming","D to attract visitors to the valley"],"correct":1,"evidence":"The main aim, according to the project manager","why":{"en":"Not restoring the landscape \"for its own sake\": the aim was to slow the river so less water reaches Ashby at once.","tr":"Manzarayı \"kendisi için\" eski hâline getirmek değil: amaç suyu yavaşlatıp Ashby’ye aynı anda daha az su ulaşmasını sağlamaktı.","fa":"نه بازگرداندن منظره «به‌خاطر خودش»: هدف کند کردن رود بود تا آب کمتری هم‌زمان به اشبی برسد."},"trap":["TR-paraphrase","TR-samewords"]},{"n":38,"kind":"mcq","prompt":"What happened during the first winter after the work was completed?","options":["A Several homes in the villages were flooded.","B The new channel had to be repaired.","C The meadows stored flood water and let it drain away gradually.","D The town centre flooded briefly."],"correct":2,"evidence":"which held the water like a sponge and released it slowly","why":{"en":"The meadows \"held the water like a sponge and released it slowly\"; the river in Ashby stayed within its banks.","tr":"Çayırlar \"suyu bir sünger gibi tuttu ve yavaşça bıraktı\"; Ashby’de nehir yatağında kaldı.","fa":"چمنزارها «آب را مثل اسفنج نگه داشتند و آرام آزاد کردند»؛ رود در اشبی از کناره‌هایش بیرون نزد."},"trap":["TR-paraphrase"]},{"n":39,"kind":"mcq","prompt":"What does the writer say about the cost of the project?","options":["A It was paid by several organisations together.","B It was higher than first planned.","C It was paid mainly by the farmers.","D It was less than the cost of new flood walls."],"correct":0,"evidence":"shared between the council, the wildlife trust and a government flood-protection fund","why":{"en":"The cost was \"shared between the council, the wildlife trust and a government flood-protection fund\".","tr":"Maliyet \"belediye, yaban hayatı vakfı ve bir devlet sel koruma fonu arasında paylaşıldı\".","fa":"هزینه «بین شهرداری، بنیاد حیات وحش و یک صندوق دولتی حفاظت از سیل تقسیم شد»."},"trap":["TR-paraphrase"]},{"n":40,"kind":"mcq","prompt":"Which statement best describes the overall tone of the article?","options":["A critical of the people who planned the project","B neutral, because there are no results yet","C enthusiastic, with no doubts at all","D generally positive, while noting some concerns"],"correct":3,"evidence":"Scientists are more cautious","why":{"en":"It reports clear benefits but also the residents’ worries and the scientist’s caution: positive, with concerns.","tr":"Açık faydaları ama aynı zamanda sakinlerin endişelerini ve bilim insanının temkinini aktarıyor: olumlu ama kaygılar da var.","fa":"فایده‌های روشن را می‌گوید، اما نگرانی ساکنان و احتیاط دانشمند را هم: مثبت، همراه با چند نگرانی."},"trap":["TR-paraphrase"]}]}],"id":"c-x10-r3-d-gt","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Fish have returned to spawn.\" To spawn is to...","options":["feed","lay eggs","die"],"correct":1,"why":{"en":"Spawn = produce eggs, for fish and frogs.","tr":"Spawn = balıklar ve kurbağalar için yumurtlamak.","fa":"spawn یعنی تخم‌ریزی، برای ماهی و قورباغه."}},{"tests":"paraphrase","point":2,"prompt":"A statement says \"the payments made it easier to agree\". Which words in an article match it?","options":["we were paid fairly, and that made the decision easier","we were not keen at first","the cattle graze there in summer"],"correct":0,"why":{"en":"Fair payment made the decision easier.","tr":"Adil ödeme kararı kolaylaştırdı.","fa":"پرداخت منصفانه تصمیم را آسان‌تر کرد."}},{"tests":"method","point":2,"prompt":"Six statements and seven people. What follows?","options":["Every person is used once","One statement has two answers","At least one person is not used"],"correct":2,"why":{"en":"Six answers from seven letters: at least one letter is left over.","tr":"Yedi harften altı cevap: en az bir harf artar.","fa":"شش جواب از هفت حرف: دست‌کم یک حرف می‌ماند."}},{"tests":"trap","point":3,"prompt":"An article praises a new library but also reports that some users find it noisy. Which description of its tone is too strong?","options":["generally positive","wholly enthusiastic","positive with some reservations"],"correct":1,"why":{"en":"\"Wholly enthusiastic\" ignores the reported problem; the other two fit.","tr":"\"Tamamen coşkulu\", aktarılan sorunu yok sayıyor; diğer ikisi uyuyor.","fa":"«کاملاً پرشور» مشکلِ گزارش‌شده را نادیده می‌گیرد؛ دو گزینه‌ی دیگر جورند."}}],"id":"c-x10-r3-x-gt","course":"ielts-exams","exam":"exam-10","unit":"x10-r3"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
